// DE VERKENNER-STAND: de tweede full-page weergave van de leesviewer.
//
// WAAROM DIT GEEN PANEEL IS (en ook geen tweede kolom). De weergaven van deze
// viewer zijn mensleesbaar; de machineleesbare graaf mag er NIET naast staan.
// Document en verkenner zijn daarom twee STANDEN van dezelfde pagina: staat de
// verkenner aan, dan is de documentweergave volledig verborgen, en andersom.
// Nooit allebei tegelijk in beeld — dat is de dragende eis, geen vormvoorkeur.
// De standen-switch buiten deze component bewaakt dat; deze component rendert
// alleen de verkenner zelf.
//
// WAAROM HET GEEN LOSSE PAGINA IS. Een eigen verken.html zou bij elke wissel
// alle bronnen opnieuw ophalen en parsen. Als stand binnen dezelfde app blijft
// de graaf staan: heen en weer springen is instant, en de URL (?verken=<IRI>)
// blijft deelbaar — pushState houdt browser-terug en -vooruit over beide
// standen heen werkend (zie verken-history.ts).
//
// DE WEERGAVE PER KNOOP is het keten-ontwerp van de vroegere graaf-inspecteur:
// de knoop zelf als grijs vlak in het midden (label, typen, curie en zijn eigen
// waarden), daarboven wat NAAR hem verwijst en daaronder waar hij zélf naar
// verwijst — dezelfde leesrichting en dezelfde randlabels als het
// Invulling-paneel. Elke IRI is een klik naar diezelfde weergave van die knoop.
//
// Gedragsbron (bevroren, niet geïmporteerd): viewer-bevroren/assets/verken-view.js
// (renderVerken) en het verkenner-blok van viewer-bevroren/assets/doc.js.
import {
  createEffect, createMemo, createSignal, For, on, onCleanup, onMount, Show,
} from 'solid-js';
import { CARD_CHUNK_SIZE, REF_LIST_INLINE_MAX, filterRefItems } from '../../model-grens.js';
import type { Verwijzing } from '../../model-grens.js';
import {
  bronnen, endpoint, graaf, graafVersie, haalVerkenKnoop, verkenBezig, verkenFout,
} from '../../stores/corpus.js';
import { tekst, weergave } from '../../stores/weergave.js';
import { predicaatTekst, refRijTekst, verkenKnoop, waardeTekst } from './verken-model.js';
import { koppelVerkenHistorie, openVerken, sluitVerken, verkenUrl } from './verken-history.js';
import { verkenHref } from './verken-url.js';
import './verken.css';
import { kopBediening } from '../gedeeld/kopselectie.js';

// De open/dicht-stand van de twee richtingblokken hoort bij DE VERKENNER, niet
// bij de knoop: wie een richting dichtklapt en dan doorklikt, wil hem dicht
// houden. null = de lezer heeft niets gezegd, dan telt de lengte. Zelfde
// afweging (en zelfde null-betekenis) als VERKEN_FOLDS in verken-view.js.
type FoldSleutel = 'up' | 'down';
const FOLDS: Record<FoldSleutel, boolean | null> = { up: null, down: null };

function foldOpen(sleutel: FoldSleutel, aantal: number): boolean {
  if (FOLDS[sleutel] != null) return !!FOLDS[sleutel];
  return aantal <= CARD_CHUNK_SIZE;
}

/** Blijft een gewone klik bij ons, of is het er een voor de browser?
 *  Modifier- en middelklik openen een nieuw tabblad/venster — zelfde regel als
 *  bij de kruisverwijzingen in het document. */
function eigenKlik(e: MouseEvent): boolean {
  return !(e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button);
}

interface RijItem { title: string; sub: string; ref: Verwijzing }

/** Eén verwijzingsrij. Een IRI is een gewone LINK (deelbaar; middelklik en
 *  "openen in nieuw tabblad" blijven werken) die bij een gewone klik binnen de
 *  pagina navigeert. Een BLANKE KNOOP krijgt geen link: hij heeft buiten dit
 *  document geen adres, en een dode link is erger dan gewone tekst. */
function RefRij(props: { item: RijItem }) {
  const ref = () => props.item.ref;
  const naam = () => (
    <span class="verken-ref-name" title={ref().desc || undefined}>{props.item.title}</span>
  );
  const pred = () => (
    <Show when={props.item.sub}>
      <span class="verken-ref-pred mono muted" title={ref().predicate?.desc || undefined}>
        {props.item.sub}
      </span>
    </Show>
  );
  return (
    <Show
      when={ref().iri}
      fallback={
        <li class="verken-ref verken-ref-anon" title={tekst('verken.anonTitle')}>
          {naam()}{pred()}
        </li>
      }
    >
      <li class="verken-ref">
        <a
          class="verken-ref-link"
          href={verkenUrl(ref().iri)}
          title={ref().iri!}
          onClick={(e) => {
            if (!eigenKlik(e)) return;
            e.preventDefault();
            openVerken(ref().iri!);
          }}
        >
          {naam()}{pred()}
        </a>
      </li>
    </Show>
  );
}

/** Eén richtingblok: LAZY (de lijst wordt pas bij het eerste openklappen
 *  gebouwd), GECHUNKT (CARD_CHUNK_SIZE per keer) en boven REF_LIST_INLINE_MAX
 *  met een filterveld. Precies de mechaniek van de vroegere inspecteur — die was
 *  er om duizenden verwijzingen niet de UI te laten plattrekken, en dat probleem
 *  is niet weg (BRP: 1.392 verwijzingen op één Offer). */
function RichtingBlok(props: {
  richting: 'in' | 'out';
  open: boolean;
  aantal: number;
  bouw: () => Verwijzing[];
  /** De knoop waar dit blok bij hoort. Wisselt hij, dan begint het blok
   *  overnieuw — zie de reset hieronder. */
  knoop: string;
}) {
  const [gebouwd, setGebouwd] = createSignal(false);
  const [filter, setFilter] = createSignal('');
  const [limiet, setLimiet] = createSignal(CARD_CHUNK_SIZE);

  // FILTER EN CHUNK HOREN BIJ DE KNOOP, NIET BIJ DE SESSIE. De bevroren viewer
  // bouwt de verkenner per knoop opnieuw op (renderVerken maakt verse DOM), dus
  // reist een ingetikt filter daar niet mee naar de volgende knoop; alleen de
  // FOLD-stand (VERKEN_FOLDS) is sessiestaat, en die staat bewust buiten deze
  // component. Solid houdt de instantie juist in leven, dus moet de reset hier
  // met de hand — zonder deze regel toonde de verkenner na een sprong 9 rijen
  // onder een randlabel dat er 1.583 beloofde (bevinding I-2).
  createEffect(on(() => props.knoop, () => {
    setFilter('');
    setLimiet(CARD_CHUNK_SIZE);
    // `gebouwd` volgt de nieuwe openstand: een DICHT blok mag zijn (dure) lijst
    // niet bouwen, en dat is precies wat het lazy ontwerp koopt.
    setGebouwd(props.open);
  }, { defer: true }));

  // Een blok dat OPEN begint moet zijn lijst ook echt hebben: in de browser
  // vuurt het toggle-event van een al open gerenderde <details> niet.
  createEffect(() => { if (props.open) setGebouwd(true); });

  const items = createMemo<RijItem[]>(() => {
    if (!gebouwd()) return [];
    return props.bouw().map((r) => {
      const txt = refRijTekst(r);
      return { title: txt.title, sub: txt.pred, ref: r };
    });
  });
  const zichtbaar = createMemo(() => filterRefItems(items(), filter()));
  const getoond = createMemo(() => zichtbaar().slice(0, limiet()));
  const rest = () => zichtbaar().length - getoond().length;

  return (
    <div class={`verken-dir verken-dir-${props.richting}`}>
      <details class="verken-fold" open={props.open}>
        {/* Een <details> zonder <summary> krijgt van de browser zijn eigen
            "Details"-regel terug; het randlabel op het vlak is de echte knop,
            dus staat de summary er wel en verbergt CSS hem. */}
        <summary class="verken-fold-sum muted" {...kopBediening()}>
          {tekst('verken.foldCount', { label: props.richting === 'in'
            ? tekst('verken.edgeIn') : tekst('verken.edgeOut'), n: props.aantal })}
        </summary>
        <Show when={gebouwd() && items().length > REF_LIST_INLINE_MAX}>
          <input
            type="search"
            class="ref-filter verken-filter"
            placeholder={tekst('verken.filterPlaceholder')}
            aria-label={tekst('verken.filterAria', {
              label: props.richting === 'in' ? tekst('verken.edgeIn') : tekst('verken.edgeOut'),
            })}
            value={filter()}
            onInput={(e) => { setFilter(e.currentTarget.value); setLimiet(CARD_CHUNK_SIZE); }}
          />
        </Show>
        <ul class="clean verken-ref-list">
          <For each={getoond()}>{(item) => <RefRij item={item} />}</For>
        </ul>
        <button
          type="button"
          class="btn ref-more"
          hidden={rest() <= 0}
          onClick={() => setLimiet((n) => n + CARD_CHUNK_SIZE)}
        >
          {rest() > 0 ? tekst('list.showMoreRest', { n: rest() }) : tekst('list.showMore')}
        </button>
      </details>
    </div>
  );
}

/** Het randlabel ÓP de rand van het grijze vlak: dezelfde vorm en dezelfde
 *  chevron-uit-CSS als in het Invulling-paneel (.fill-edge), want het is
 *  hetzelfde gebaar op hetzelfde soort blok. Het label is ook de knop. */
function RandLabel(props: {
  richting: 'in' | 'out'; open: boolean; onToggle: () => void; tekst: string;
}) {
  const omhoog = () => props.richting === 'in';
  const wissel = () => props.onToggle();
  return (
    <p
      class={'fill-edge verken-edge is-foldable fill-edge-' + (omhoog() ? 'up' : 'down')}
      role="button"
      tabindex="0"
      aria-expanded={props.open}
      onClick={wissel}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); wissel(); }
      }}
    >
      <span>{omhoog() ? '↑ ' : '↓ '}</span>
      <span>{props.tekst}</span>
    </p>
  );
}

export interface VerkennerProps {
  /** "Toon in document": de verkenner sluit zichzelf en meldt de knoop, zodat
   *  de documentweergave ernaartoe kan springen (revealInUi in de oude viewer).
   *  De sprong zelf hoort bij de documentkant en staat dus buiten deze stand. */
  onToonInDocument?: (iri: string) => void;
}

export function Verkenner(props: VerkennerProps) {
  // Een NIEUWE verkennersessie begint met de standaardstand van de twee
  // richtingblokken; binnen één sessie wint de keuze van de lezer.
  onMount(() => { FOLDS.up = null; FOLDS.down = null; });
  // Browser-terug/vooruit over de standen heen (bevinding I4). Idempotent: de
  // standen-switch mag hem óók op app-niveau koppelen.
  onCleanup(koppelVerkenHistorie());

  const iri = () => weergave.verkenIri;

  // ENDPOINTMODUS: de geladen graaf is op policies gericht en zegt over een
  // willekeurige knoop hooguit dát er naar verwezen wordt. Elke navigatiestap
  // haalt daarom die ene knoop bij (één CONSTRUCT), één keer per knoop.
  //
  // OOK OP DE GRAAF WACHTEN, niet alleen op de knoop. Een gedeelde link
  // (?sparql=…&verken=…) opent de verkenner terwijl de lijstlading nog loopt;
  // de bijgemengde triples hebben dan nog geen graaf om in te landen. Zolang
  // die er niet is doet deze stand niets, en zodra hij er is loopt het effect
  // alsnog. (Zonder deze afhankelijkheid liet de verkenner in endpointmodus
  // precies de uitgaande verwijzingen van de knoop weg — gemeten op /brp-ap:
  // "Verwijst naar (1)" in plaats van (11).)
  createEffect(on([iri, graaf], ([i, g]) => {
    if (i && g && endpoint()) void haalVerkenKnoop(i);
  }));

  const knoop = createMemo(() => {
    void weergave.lang;      // hertalen bouwt het knoopmodel opnieuw op
    void graafVersie();      // een bijgemengde knoop telt mee
    const g = graaf();
    const i = iri();
    return g && i ? verkenKnoop(g, i) : null;
  });

  const [inOpen, setInOpen] = createSignal(true);
  const [uitOpen, setUitOpen] = createSignal(true);
  // De standaardstand hangt aan de TELLING (foldOpen); bij elke knoopwissel
  // opnieuw bepalen, met de keuze van de lezer als die er is.
  createEffect(() => {
    const m = knoop();
    if (!m) return;
    setInOpen(foldOpen('up', m.inCount));
    setUitOpen(foldOpen('down', m.outCount));
  });

  const wisselIn = () => { const n = !inOpen(); FOLDS.up = n; setInOpen(n); };
  const wisselUit = () => { const n = !uitOpen(); FOLDS.down = n; setUitOpen(n); };

  const randTekst = (richting: 'in' | 'out', n: number) => tekst('verken.foldCount', {
    label: richting === 'in' ? tekst('verken.edgeIn') : tekst('verken.edgeOut'), n,
  });

  const comunicaHref = () => verkenHref(iri(), {
    sources: bronnen(),
    sparqlEndpoint: endpoint(),
  }, { pageUrl: typeof location !== 'undefined' ? location.href : null });

  return (
    <Show when={knoop()}>{(m) => (
      <div class="verken">
        {/* 1. INKOMEND, bovenaan: wat naar deze knoop wijst. Zelfde leesrichting
               als het Invulling-paneel (↑ boven het vlak, ↓ eronder). */}
        <Show when={m().inCount}>
          <RichtingBlok richting="in" knoop={iri() ?? ''} open={inOpen()}
            aantal={m().inCount} bouw={m().incoming} />
        </Show>

        {/* 2. HET CENTRALE VLAK: de knoop zelf. */}
        <div class="verken-cur">
          <Show when={m().inCount}>
            <RandLabel richting="in" open={inOpen()} onToggle={wisselIn}
              tekst={randTekst('in', m().inCount)} />
          </Show>

          <div class="verken-title-row">
            <h1 class="verken-label" title={m().node.desc || undefined}>
              {m().node.label || tekst('anon')}
            </h1>
            {/* DE TERUGWEG. Een gewone link naar dezelfde pagina zonder ?verken=,
                zodat hij deelbaar is en in een nieuw tabblad geopend kan worden;
                bij een gewone klik wisselt de app van stand zónder te herladen. */}
            <Show when={m().node.iri}>
              <a
                class="btn verken-back"
                href={verkenUrl(null)}
                title={tekst('verken.backTitle')}
                onClick={(e) => {
                  if (!eigenKlik(e)) return;
                  e.preventDefault();
                  const doel = m().node.iri!;
                  sluitVerken();
                  props.onToonInDocument?.(doel);
                }}
              >{tekst('verken.back')}</a>
            </Show>
          </div>

          <Show when={m().node.types.length}>
            <div class="verken-types muted">{m().node.types.join(' · ')}</div>
          </Show>
          <div class="verken-curie mono" title={m().node.iri || undefined}>
            {m().node.curie || tekst('anon')}
          </div>

          <Show when={verkenBezig()}>
            <p class="verken-status muted">{tekst('verken.loading')}</p>
          </Show>
          <Show when={verkenFout()}>
            <p class="verken-status verken-err">{verkenFout()}</p>
          </Show>

          {/* De WAARDEN van de knoop: zijn literals, als label/waarde-rijen. Dit
              is wat een knoop over zichzelf zegt en dus de inhoud van het vlak. */}
          <Show
            when={m().values.length}
            fallback={
              <Show when={m().bare}>
                <p class="verken-none muted">{tekst('verken.noTriples')}</p>
              </Show>
            }
          >
            <dl class="verken-values">
              <For each={m().values}>{(v) => (
                <>
                  <dt class="verken-val-key" title={v.predicate?.desc || undefined}>
                    {predicaatTekst(v.predicate)}
                  </dt>
                  <dd class="verken-val">{waardeTekst(v)}</dd>
                </>
              )}</For>
            </dl>
          </Show>

          {/* DE EXTERNE CLIENT blijft bestaan als hulpmiddel, niet als weergave:
              wie een echte query wil draaien (of de ruwe Turtle wil zien) gaat
              naar de meegeleverde Comunica-bundel. Een ANDERE pagina in een
              ander tabblad — nooit iets wat naast het document komt te staan. */}
          <Show when={comunicaHref()}>
            <p class="verken-tools">
              <a
                class="verken-sparql"
                href={comunicaHref()!}
                target="_blank"
                rel="noopener"
                title={tekst('verken.sparqlTitle')}
              >{tekst('verken.sparql')}</a>
            </p>
          </Show>

          <Show when={m().outCount}>
            <RandLabel richting="out" open={uitOpen()} onToggle={wisselUit}
              tekst={randTekst('out', m().outCount)} />
          </Show>
        </div>

        {/* 3. UITGAAND, eronder. */}
        <Show when={m().outCount}>
          <RichtingBlok richting="out" knoop={iri() ?? ''} open={uitOpen()}
            aantal={m().outCount} bouw={m().outgoing} />
        </Show>
      </div>
    )}</Show>
  );
}
